export const skillImportRoleEnum = {
    user: "user",
    assistant: "assistant",
    tool_call: "tool_call",
    tool_result: "tool_result"
} as const;

export type SkillImportRoleEnumKey = (typeof skillImportRoleEnum)[keyof typeof skillImportRoleEnum];

/**
 * @description Allowed values of `messages[].role` in the `/skill/import` request. Extends the `user` / `assistant` of L0 add\n(`ConversationRole`) with two more:\n- `tool_call`: a tool call initiated by the model;\n- `tool_result`: the result returned by a tool call.\n
 * @example tool_call
*/
export type SkillImportRole = SkillImportRoleEnumKey;

/**
 * @description A conversation message used for extraction. Its shape is exactly the same as `ConversationItem`\n(`{role, content, timestamp}`), except `role` uses `SkillImportRole`\nto carry the two roles `tool_call` / `tool_result`.\n\nSemantic constraints:\n- All roles: `content` must be non-empty.\n- `tool_call`: the tool name and arguments are serialized/summarized by the caller into `content`;\n  the server does not parse them structurally.\n- `tool_result`: the tool result or error message is likewise serialized/summarized by the caller\n  into `content`.\n- The pairing of call/result is expressed by the relative order in `messages[]` and the `content`\n  itself; the server keeps no explicit pairing key.\n
*/
export type SkillImportMessage = {
    /**
     * @description Allowed values of `messages[].role` in the `/skill/import` request. Extends the `user` / `assistant` of L0 add\n(`ConversationRole`) with two more:\n- `tool_call`: a tool call initiated by the model;\n- `tool_result`: the result returned by a tool call.\n
     * @type string
    */
    role: SkillImportRole;
    /**
     * @description Body text in the same shape as L0 add. For `tool_call` / `tool_result` it is\nthe caller's serialized or summarized form of the tool name, arguments, result or error.\n
     * @minLength 1
     * @maxLength 8192
     * @type string
    */
    content: string;
    /**
     * @type string | undefined, date-time
    */
    timestamp?: string;
};

export type SkillImportRequest = (IdFields & {
    /**
     * @description Business-side session ID; same meaning as in L0 add. It is written into the extracted artifact's\n`source_refs.session_id` for later provenance. It does not trigger\nthe server to implicitly fetch data across endpoints.\n
     * @type string | undefined
    */
    session_id?: string;
    /**
     * @type array
    */
    messages: SkillImportMessage[];
});

